namespace RisingLands;
public static class SanctuaryTests {
 static void Check(bool value,string name){if(!value)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);}
 static void Wait(Simulation s){for(int i=0;i<15000&&s.ResidentTrips.Count>0;i++)s.Step();if(s.ResidentTrips.Count>0)throw new Exception("Reversion arrival timeout");}
 static void RoundTrip(Simulation s,string root,string name){string saved=s.Serialize();var copy=MissionOneTests.Load(root);copy.Restore(saved);Check(copy.Serialize()==saved,name);}
 public static void Run(string root){
  foreach(int type in new[]{5,7}){var s=MissionOneTests.Load(root);var home=s.World.Buildings.First(b=>b.Owner==0&&b.Type==2);s.ReleaseResident(home.Slot);var actor=s.World.Units.First(a=>a.Type==type&&a.Owner==0);int oldType=actor.Type;
   Check(s.EnterBuilding(actor,home.Slot)&&actor.Type==oldType,"worker "+type+" reverts only after arrival");RoundTrip(s,root,"worker "+type+" pending entry round trip");Wait(s);Check(actor.Type==9&&actor.LegacyState==14&&s.World.BuildingResidents[home.Slot].Contains(actor.Slot),"worker "+type+" becomes actual resident colonist");RoundTrip(s,root,"worker "+type+" converted save round trip");
   var ids=s.World.BuildingResidents[home.Slot];ids.Remove(actor.Slot);ids.Insert(0,actor.Slot);Check(s.Recruit(5,home.Slot)&&s.Recruitments.Last().SettlerSlot==actor.Slot,"converted worker "+type+" can train again");for(int i=0;i<3000&&!s.Recruitments.Last().Finished;i++)s.Step();Check(actor.Type==5,"converted worker "+type+" completes retraining");RoundTrip(s,root,"retrained original worker "+type+" save round trip");
   Check(s.EnterBuilding(actor,home.Slot),"retrained worker "+type+" may revert again");Wait(s);RoundTrip(s,root,"repeated reversion worker "+type+" save round trip");
  }
  foreach(int type in new[]{5,7}){var loaded=MissionOneTests.Load(root);var home=loaded.World.Buildings.First(b=>b.Type==2&&b.Owner==0);loaded.ReleaseResident(home.Slot);var worker=loaded.World.Units.First(a=>a.Type==type&&a.Owner==0);int resource=type==5?0:4;loaded.World.Resources[resource]-=2;if(type==5){worker.Food=2;worker.CargoKind=1;worker.FoodField=5642;}else{worker.Rock=2;worker.RockDestination=home.Slot;}long piles=loaded.World.Quantities.Where((q,i)=>loaded.World.Objects[i]==(type==5?67:68)).Sum(q=>(long)q);Check(loaded.EnterBuilding(worker,home.Slot),"loaded worker "+type+" receives reversion order");Wait(loaded);Check(worker.Type==9&&worker.Food==0&&worker.Rock==0&&loaded.World.Quantities.Where((q,i)=>loaded.World.Objects[i]==(type==5?67:68)).Sum(q=>(long)q)==piles+2,"loaded worker "+type+" preserves cargo on ground before reversion");RoundTrip(loaded,root,"loaded worker "+type+" clean colonist save round trip");}
  foreach(int type in new[]{0,1,8}){var soldierSim=MissionOneTests.Load(root);var home=soldierSim.World.Buildings.First(b=>b.Type==2&&b.Owner==0);soldierSim.ReleaseResident(home.Slot);var soldier=soldierSim.World.Units.First(a=>a.Type==type&&a.Owner==0&&VisualCatalog.Visible(a));Check(soldierSim.EnterBuilding(soldier,home.Slot),"soldier "+type+" may enter sanctuary");Wait(soldierSim);Check(soldier.Type==9&&soldier.LegacyState==14,"soldier "+type+" becomes colonist");RoundTrip(soldierSim,root,"soldier "+type+" reversion round trip");}
  var engineerSim=MissionOneTests.Load(root);var engineerHome=engineerSim.World.Buildings.First(b=>b.Type==2&&b.Owner==0);Check(engineerSim.Recruit(6,engineerHome.Slot),"train engineer for sanctuary return");for(int i=0;i<3000&&!engineerSim.Recruitments.Last().Finished;i++)engineerSim.Step();var engineer=engineerSim.World.Units.First(a=>a.Slot==engineerSim.Recruitments.Last().SettlerSlot);Check(engineerSim.EnterBuilding(engineer,engineerHome.Slot),"engineer may enter sanctuary");Wait(engineerSim);RoundTrip(engineerSim,root,"engineer reversion round trip");
  var full=MissionOneTests.Load(root);var fullHome=full.World.Buildings.First(b=>b.Type==2&&b.Owner==0);var blocked=full.World.Units.First(a=>a.Type==5&&a.Owner==0);while(full.Occupants(fullHome.Slot)+full.ResidentTrips.Count<full.ResidentCapacity(fullHome))full.ResidentTrips.Add(new(){Slot=10000+full.ResidentTrips.Count,Building=fullHome.Slot,Cell=fullHome.Cell});Check(!full.CanEnterBuilding(blocked,fullHome.Slot),"full sanctuary rejects reversion without altering profession");
  var preview=MissionOneTests.Load(root);Check(preview.NextMissionTechnologies(0).Select(t=>t.Key).SequenceEqual(new[]{"AGRICULTURE2","AGRICULTURE3"}),"agriculture preview matches next two native harvesting improvements");Check(preview.NextMissionTechnologies(1).Select(t=>t.Key).SequenceEqual(new[]{"MILITAIRE2","MILITAIRE3"}),"military preview matches combat damage then incendiary unlock");Check(preview.NextMissionTechnologies(2).Select(t=>t.Key).SequenceEqual(new[]{"GENIECIVIL4","GENIECIVIL5"}),"engineering preview shows laboratory and exchange research without granting them instantly");Check(preview.NextMissionTechnologies(3).Length==0,"religious preview does not promise mission-seven technologies in mission two");
  var trained=MissionOneTests.Load(root);var sanctuary=trained.World.Buildings.First(b=>b.Type==2&&b.Owner==0);Check(trained.Recruit(5,sanctuary.Slot),"create trained farmer for reversion");for(int i=0;i<3000&&!trained.Recruitments.Last().Finished;i++)trained.Step();var farmer=trained.World.Units.First(a=>a.Slot==trained.Recruitments.Last().SettlerSlot);Check(trained.EnterBuilding(farmer,sanctuary.Slot),"finished training history does not block sanctuary entry");Wait(trained);RoundTrip(trained,root,"trained farmer reversion keeps paid training history");var residents=trained.World.BuildingResidents[sanctuary.Slot];residents.Remove(farmer.Slot);residents.Insert(0,farmer.Slot);Check(trained.Recruit(7,sanctuary.Slot),"same colonist may train a second profession");for(int i=0;i<3000&&!trained.Recruitments.Last().Finished;i++)trained.Step();Check(farmer.Type==7,"second profession completed");RoundTrip(trained,root,"multiple paid trainings on same slot round trip");
  Check(trained.EnterBuilding(farmer,sanctuary.Slot),"twice trained unit returns to sanctuary");Wait(trained);RoundTrip(trained,root,"twice trained unit reversion round trip");
 }
}
